def refs(txt):
    out=e(txt)
    out=out.replace('[S1~S8]',' · '.join(f'<a href="#S{i}">S{i}</a>' for i in range(1,9)))
    return re.sub(r'\[(S\d+(?:, S\d+)*)\]',lambda m:' · '.join(f'<a href="#{s}">{s}</a>' for s in m.group(1).split(', ')),out)
def ul(xs):return '<ul>'+''.join('<li>'+refs(x)+'</li>' for x in xs)+'</ul>'
def codes(xs):return '<ul class="code-links">'+''.join(f'<li><a href="https://github.com/embrain82/2609_Pension_Monopoly/blob/{COMMIT}/{f}#L{n}" target="_blank" rel="noopener">{e(f)}:{n}</a></li>' for f,n in xs)+'</ul>'
def evlinks(ids):return ' · '.join(f'<a href="{e(EVIDENCE[id][1])}" target="_blank" rel="noopener">{id} {e(EVIDENCE[id][0])}</a>' for id in ids)
def card(i):
    deps=' · '.join(f'<a href="#{d}">{d}</a>' for d in i['dependencies']) or '독립 착수 가능'
    return f'''<article class="proposal" id="{i['id']}" data-category="{i['id'][0]}" data-priority="{i['priority']}">
    <div class="card-top"><div><span class="id-label">{i['id']}</span> <span class="priority {i['priority']}">{i['priority']}</span> <span class="muted">{e(i['effort'])}</span><h3>{e(i['title'])}</h3></div><label class="pick"><input type="checkbox" value="{i['id']}" aria-label="{i['id']} 검토 목록에 담기" {'disabled' if i['priority']=='P0' else ''}>검토에 담기</label></div>
    <p class="problem"><b>발견한 점</b> {e(i['problem'])}</p><p class="solution"><b>제안</b> {e(i['proposal'])}</p>
    <p class="simple"><span>복잡도 관리</span> {e(i['simple'])}</p>
    <details class="implementation"><summary>근거 · 구현 단계 · 검증 기준 자세히 보기</summary>
    <p class="evidence-line">{evlinks(i['evidence'])}</p><div class="two-col"><section><h4>구현 순서</h4><ol>{''.join('<li>'+e(x)+'</li>' for x in i['steps'])}</ol></section><section><h4>완료 조건</h4>{ul(i['tests'])}</section></div>
    <div class="two-col"><section><h4>수정할 코드·문서</h4>{codes(i['files'])}</section><section><h4>선행·연계 후보</h4><p>{deps}</p><p class="muted">연계 항목도 자동 승인되지 않습니다. 일부만 컨펌하면 기존 동작을 유지하는 대안을 먼저 적용 범위에 명시합니다.</p></section></div>
    <h4>저장·기존 플레이 영향</h4><p>{e(i['compat'])}</p><h4>제도·표현 경계</h4><p>{refs(i['guard'])}</p>
    <p class="status">상태: {e(i['status'])}</p></details></article>'''
def table(prefix):
    rows=''.join(f'<tr><td><a href="#{x["id"]}">{x["id"]}</a></td><td><a href="#{x["id"]}">{e(x["title"])}</a></td><td><span class="priority {x["priority"]}">{x["priority"]}</span></td><td>{e(x["effort"])}</td></tr>' for x in ITEMS if x['id'].startswith(prefix))
    return '<div class="table-scroll"><table><thead><tr><th>번호</th><th>개선 후보</th><th>우선</th><th>작업량</th></tr></thead><tbody>'+rows+'</tbody></table></div>'
