gallery_ids=['C01','B02','A09','A08','A13','A03']
gallery='<section class="panel" id="evidence"><h2>실제 화면 근거</h2><p class="muted">이미지를 누르면 원본을 볼 수 있습니다. C01만 별도 경계조건 화면이며 나머지는 실제 Ego Browser 플레이 캡처입니다.</p><div class="gallery">'+''.join(f'<figure><a href="{EVIDENCE[k][1]}" target="_blank" rel="noopener"><img loading="lazy" src="{EVIDENCE[k][1]}" alt="{e(k+" · "+EVIDENCE[k][0])}"></a><figcaption><b>{e(k+" · "+EVIDENCE[k][0])}</b><br>{e(EVIDENCE[k][2])}</figcaption></figure>' for k in gallery_ids)+'</div><details><summary>전체 근거 목록</summary><ul>'+''.join(f'<li><a href="{v[1]}" target="_blank" rel="noopener">{k} · {e(v[0])}</a> — {e(v[2])}</li>' for k,v in EVIDENCE.items())+'</ul></details></section>'
sources='<section class="panel" id="sources"><h2>공식 근거와 검토 시점</h2>'+''.join(f'<div class="source" id="{k}"><b>{k}</b> · <a href="{e(v[1])}" target="_blank" rel="noopener">{e(v[0])}</a><p>{e(v[2])}</p></div>' for k,v in SOURCES.items())+'<p class="small">S9 추가: <a href="https://www.w3.org/WAI/WCAG22/Understanding/target-size-minimum.html">W3C 클릭 대상 최소 크기</a>. 자료는 필요한 개념을 요약했으며, 공식 문서 원문을 그대로 옮긴 자료가 아닙니다.</p></section>'
script='''
const cards=[...document.querySelectorAll('.proposal')], checks=[...document.querySelectorAll('.pick input')];
const $=s=>document.querySelector(s);const data=JSON.parse($('#items-data').textContent);
function updateSelection(){const ids=checks.filter(c=>c.checked).map(c=>c.value);$('#selected-count').textContent=ids.length;$('#selected-inline').textContent=ids.length;$('#selection-text').value=ids.length?'검토용 선택 목록 (아직 구현 승인 아님)\\n'+ids.map(id=>id+' · '+data.find(x=>x.id===id).title).join('\\n')+'\\n\\n컨펌할 항목은 대화에서 번호로 알려주세요.':'선택한 항목이 없습니다. 상세 계획을 읽고 검토할 항목을 담아보세요.';}
checks.forEach(c=>c.addEventListener('change',updateSelection));
function filter(){const category=$('#category-filter').value,priority=$('#priority-filter').value,q=$('#query').value.toLowerCase().trim();let count=0;cards.forEach(c=>{c.hidden=Boolean((category&&c.dataset.category!==category)||(priority&&c.dataset.priority!==priority)||(q&&!c.textContent.toLowerCase().includes(q)));if(!c.hidden)count++});$('#visible-count').textContent=count;$('#empty').hidden=count>0;}
['#category-filter','#priority-filter','#query'].forEach(s=>$(s).addEventListener('input',filter));
$('#pick-p0').addEventListener('click',()=>{location.hash='F01'});
$('#clear-picks').addEventListener('click',()=>{checks.forEach(c=>c.checked=false);updateSelection()});
$('#expand-all').addEventListener('click',()=>{cards.filter(c=>!c.hidden).forEach(c=>c.querySelector('details').open=true)});
$('#collapse-all').addEventListener('click',()=>cards.forEach(c=>c.querySelector('details').open=false));
async function copy(){try{await navigator.clipboard.writeText($('#selection-text').value);$('#copy-status').textContent='검토 목록을 복사했습니다.'}catch{$('#selection-text').focus();$('#selection-text').select();$('#copy-status').textContent='선택된 텍스트를 복사해 주세요.'}}
$('#copy-selection').addEventListener('click',copy);$('#download-selection').addEventListener('click',()=>{const blob=new Blob([$('#selection-text').value],{type:'text/plain;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='pension-road-review-selection.txt';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)});
function reveal(){const id=location.hash.slice(1),c=document.getElementById(id);if(c?.classList.contains('proposal')){$('#category-filter').value='';$('#priority-filter').value='';$('#query').value='';filter();c.querySelector('details').open=true;requestAnimationFrame(()=>c.scrollIntoView({block:'start'}))}}
window.addEventListener('hashchange',reveal);reveal();
const demos={pension:['50.4 / 50만원',100,'목표용 월 환산액 · 세전. 실제 세후 수령 비교는 별도입니다.'],cushion:['921 / 1,800만원',51.2,'순생활자금 목표 · 부족한 생활자금 약 879만원. 연금액은 보조 정보입니다.'],purchasing:['88.5 / 100',88.5,'물가 반영 운용지수 · 구매력을 지키는 미션입니다.']};
$('#mission-demo').addEventListener('change',ev=>{const d=demos[ev.target.value];$('#mission-value').textContent=d[0];$('#mission-meter').style.width=d[1]+'%';$('#mission-explain').textContent=d[2]});
$('#flow-demo').addEventListener('input',ev=>{const amount=Number(ev.target.value);$('#flow-amount').textContent=(amount/10000).toLocaleString('ko-KR')+'만원';$('#flow-growth').textContent='잔액 증가 +'+(amount/108000000*100).toFixed(1)+'%'});
let priorOpen=[];window.addEventListener('beforeprint',()=>{priorOpen=[...document.querySelectorAll('details')].map(d=>[d,d.open]);priorOpen.forEach(([d])=>d.open=true)});window.addEventListener('afterprint',()=>priorOpen.forEach(([d,open])=>d.open=open));
updateSelection();filter();
'''
body=f'''<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>연금로드 · 직접 플레이 리뷰와 20개 구현 계획</title><meta name="description" content="Ego Browser 24턴 플레이 근거, 기능 개선 10개와 디자인 개선 10개, 단계별 구현 및 검증 계획"><style>{css}</style></head><body>
<header class="hero"><div class="eyebrow">PENSION ROAD · PLAY REVIEW · 2026.09.12</div><h1>더 쉽게 판단하고,<br>더 재미있게 완주하기</h1><p>연금로드 v1.6.0 직접 플레이 리뷰<br>기능·과정·설명 10가지 + 시각 디자인 10가지의 상세 구현 계획</p><div class="badge-row"><span class="hero-badge">Ego Browser 직접 플레이</span><span class="hero-badge">공식 제도 자료 대조</span><span class="hero-badge"><strong>컨펌한 항목만 구현</strong></span></div><p class="meta">검토 기준 {COMMIT[:7]} · 리뷰 당시 운영본 기준 · 승인 상태: F01~F04 구현 완료 · 나머지 16개 컨펌 대기</p></header>
<nav class="top" aria-label="보고서 목차"><a href="#findings">핵심 발견</a><a href="#overview">20개 목록</a><a href="#examples">개선 예시</a><a href="#details">상세 계획</a><a href="#rules">제도 점검</a><a href="#sequence">구현 순서</a><a href="#selection">컨펌 후보</a></nav><noscript>모든 계획은 JavaScript 없이도 읽을 수 있습니다. 항목 선택·필터·예시는 JavaScript가 필요합니다.</noscript><main class="wrap">{intro}{gallery}
<section class="panel" id="overview"><h2>20개 개선 후보 한눈에 보기</h2><p class="muted">번호를 누르면 상세 계획이 열립니다. 기존 FB-001~006의 완료 상태와 별도로 관리하는 새 리뷰 후보입니다.</p><p><b>후속 P1 갱신 · 2026-09-12:</b> 사용자 요청 FB-007(시작 전 성향 확인 → 디폴트옵션 선택 → 게임 시작)을 추가했습니다. <a href="../../backlog/p1-scope-2026-09-12.md">P1 최신 목록은 기존 11개 + 신규 1개, 총 12개</a>입니다. 아래는 최초 20개 리뷰를 보존한 목록이며, 신규 항목의 등록만으로 구현을 시작하지 않습니다.</p><h3>기능·과정·설명 10가지</h3>{table('F')}<h3 style="margin-top:30px">시각 디자인 10가지</h3>{table('D')}</section>
{mocks}{regulations}{schedule}
<section id="details"><h2>항목별 상세 구현 계획</h2><p>문제 → 제안 → 구현 단계 → 완료 조건 → 저장 영향 순서로 검토할 수 있습니다.</p><div class="filters"><label>분류 <select id="category-filter"><option value="">전체</option><option value="F">기능·과정·설명</option><option value="D">시각 디자인</option></select></label><label>우선순위 <select id="priority-filter"><option value="">전체</option><option>P0</option><option>P1</option><option>P2</option></select></label><input id="query" type="search" placeholder="금리, 포트폴리오, F01…" aria-label="개선 항목 검색"><button id="expand-all">표시 항목 펼치기</button><button id="collapse-all">접기</button><span class="muted right"><b id="visible-count">20</b>개 표시</span></div><p id="empty" class="empty" hidden>조건에 맞는 항목이 없습니다. 필터나 검색어를 바꿔 주세요.</p>{''.join(card(i) for i in ITEMS)}</section>
<section class="approval" id="selection"><h2>컨펌할 후보를 골라보세요</h2><p>각 항목의 “검토에 담기”는 개인 검토 메모입니다. <b>체크만으로 구현을 승인하거나 게임에 적용하지 않습니다.</b> 내용을 확인한 뒤 대화에서 <b>“F05·F06·D04 진행”</b>처럼 번호를 알려주시면 해당 범위를 구현합니다.</p><p>현재 담은 후보 <b id="selected-inline">0</b>개</p><button id="pick-p0">승인된 P0 4개 보기</button><button id="clear-picks">선택 비우기</button><label for="selection-text">검토 메모</label><textarea id="selection-text" readonly></textarea><button id="copy-selection">목록 복사</button><button id="download-selection">목록 내려받기</button><p id="copy-status" role="status"></p><small>새로고침 전 목록을 복사하거나 내려받으세요. 이 보고서는 외부로 메모를 전송하지 않습니다.</small></section>{sources}<p class="footer">이 문서는 검토와 계획을 위한 산출물입니다. 사용자가 승인한 F01~F04의 v1.6.1 구현과 검증을 진행했습니다. <a href="../../implementation/2026-09-12-review-p0.md">P0 구현·검증 기록</a>. 나머지 16개 제안은 적용하지 않았습니다. <a href="review-items.json">구조화된 20개 목록</a> · <a href="README.md">검토 기록</a> · <a href="../../backlog/review-candidates-2026-09-12.md">승인 상태 관리</a></p></main><aside class="floating" aria-label="선택한 검토 후보"><div><b>검토 후보 <span id="selected-count">0</span>개 선택</b><br><small>체크는 검토 메모 · 구현은 대화에서 별도 컨펌</small></div><a href="#selection">목록 확인 →</a></aside><script type="application/json" id="items-data">{json.dumps([dict(id=x['id'],title=x['title'],priority=x['priority']) for x in ITEMS],ensure_ascii=False).replace('<','\\u003c')}</script><script>{script}</script></body></html>'''
(ROOT/'review-and-implementation-plan.html').write_text(body)
(ROOT/'review-items.json').write_text(json.dumps({'version':'review-2026-09-12','baselineCommit':COMMIT,'status':'p0-implemented-others-awaiting-confirmation','recommendedOrder':ORDER,'items':ITEMS},ensure_ascii=False,indent=2))
print('Created',len(ITEMS),'proposals;',len(body),'characters')
